solution.solution.cpp:
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <sstream>
#include <string>
#include <vector>

struct Leak
{
    int allocation;
    std::uint64_t address;
    std::size_t size;
    std::string file;
    int line;
    std::vector<std::uint8_t> data;
};

std::vector<Leak> parseLeakReport(const std::string& report)
{
    std::vector<Leak> leaks;
    std::istringstream in{ report };
    std::string text;
    while (std::getline(in, text))
    {
        if (!text.empty() && text.back() == '\r') text.pop_back();
        const std::size_t brace{ text.find('{') };
        const std::size_t block{ text.find("} normal block at 0x") };
        if (brace != std::string::npos && block != std::string::npos && block > brace)
        {
            Leak leak{};
            leak.allocation = std::stoi(text.substr(brace + 1, block - brace - 1));
            const std::size_t addressAt{ block + 20 };
            const std::size_t comma{ text.find(',', addressAt) };
            leak.address = std::stoull(text.substr(addressAt, comma - addressAt), nullptr, 16);
            leak.size = static_cast<std::size_t>(std::stoull(text.substr(comma + 2)));
            const std::size_t colon{ text.rfind(") : ", brace) };
            if (colon != std::string::npos)
            {
                const std::size_t open{ text.rfind('(', colon) };
                leak.file = text.substr(0, open);
                leak.line = std::stoi(text.substr(open + 1, colon - open - 1));
            }
            leaks.push_back(leak);
            continue;
        }
        const std::size_t dataAt{ text.find("Data: <") };
        if (dataAt != std::string::npos && !leaks.empty())
        {
            const std::size_t close{ text.find("> ", dataAt + 7) };
            if (close == std::string::npos) continue;
            std::istringstream hex{ text.substr(close + 2) };
            std::string pair;
            while (hex >> pair) leaks.back().data.push_back(static_cast<std::uint8_t>(std::stoul(pair, nullptr, 16)));
        }
    }
    return leaks;
}

std::size_t totalLeaked(const std::vector<Leak>& leaks)
{
    std::size_t total{ 0 };
    for (const Leak& l : leaks) total += l.size;
    return total;
}

std::vector<int> neverWritten(const std::vector<Leak>& leaks)
{
    std::vector<int> numbers;
    for (const Leak& l : leaks)
        if (!l.data.empty() && std::all_of(l.data.begin(), l.data.end(), [](std::uint8_t b) { return b == 0xCD; }))
            numbers.push_back(l.allocation);
    std::sort(numbers.begin(), numbers.end());
    return numbers;
}

unitTests:
static const std::string REPORT{
    "Detected memory leaks!\n"
    "Dumping objects ->\n"
    "C:\\src\\level.cpp(14) : {157} normal block at 0x000001C4B2E8F0A0, 40 bytes long.\n"
    " Data: <                > CD CD CD CD CD CD CD CD CD CD CD CD CD CD CD CD \n"
    "{156} normal block at 0x000001C4B2E91230, 8 bytes long.\n"
    " Data: <*       > 2A 00 00 00 00 00 00 00 \n"
    "{12} normal block at 0x000001C4B2E00010, 4 bytes long.\n"
    " Data: <    > CD CD CD CD \n"
    "Object dump complete.\n" };

TEST("blocks are found") {
    const auto leaks{ parseLeakReport(REPORT) };
    CHECK_EQ(leaks.size(), 3u);
    if (leaks.size() != 3) return;
    CHECK_EQ(leaks[0].allocation, 157);
    CHECK_EQ(leaks[0].address, 0x000001C4B2E8F0A0ull);
    CHECK_EQ(leaks[0].size, 40u);
    CHECK_EQ(leaks[1].allocation, 156);
    CHECK_EQ(leaks[2].size, 4u);
}
TEST("files and lines") {
    const auto leaks{ parseLeakReport(REPORT) };
    if (leaks.size() != 3) { CHECK(false); return; }
    CHECK_EQ(leaks[0].file, std::string("C:\\src\\level.cpp"));
    CHECK_EQ(leaks[0].line, 14);
    CHECK_EQ(leaks[1].file, std::string(""));
    CHECK_EQ(leaks[1].line, 0);
}
TEST("data bytes") {
    const auto leaks{ parseLeakReport(REPORT) };
    if (leaks.size() != 3) { CHECK(false); return; }
    CHECK_EQ(leaks[0].data.size(), 16u);
    CHECK_EQ(leaks[1].data, (std::vector<std::uint8_t>{ 0x2A, 0, 0, 0, 0, 0, 0, 0 }));
}
TEST("summaries") {
    const auto leaks{ parseLeakReport(REPORT) };
    CHECK_EQ(totalLeaked(leaks), 52u);
    CHECK_EQ(neverWritten(leaks), (std::vector<int>{ 12, 157 }));
    CHECK(parseLeakReport("No leaks here.\n").empty());
    CHECK_EQ(totalLeaked({}), 0u);
}
TEST("Windows line endings") {
    const auto leaks{ parseLeakReport("{7} normal block at 0x10, 2 bytes long.\r\n Data: <  > CD CD \r\n") };
    CHECK_EQ(leaks.size(), 1u);
    if (!leaks.empty()) { CHECK_EQ(leaks[0].address, 0x10ull); CHECK_EQ(leaks[0].data.size(), 2u); }
}

